const visual = {
  prepare: function (input) {
    var texts = [
      '拔塞过程：u = x / h',
      '木塞上移 x = u·h（三段位移按真实比例）',
      'u = 0',
      'u = 1/2',
      'u = 1',
      '瓶口基准线',
      'x',
      '木塞底部到达瓶口'
    ];
    var out = [];
    for (var i = 0; i < texts.length; i++) {
      out.push({ kind: 'text', payload: texts[i] });
    }
    return out;
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var W = vp.widthDu || 720;
    var H = vp.heightDu || 420;
    var pw = W / 3;
    var h = H * 0.27;
    var neckHalf = Math.min(pw * 0.15, 30);
    var corkHalf = Math.max(neckHalf - 4, 6);
    var Ym = H * 0.58;
    var neckBottom = Math.min(Ym + h + H * 0.02, H * 0.88);
    var labelY = H * 0.93;
    var subY = H * 0.975;

    var paths = [];
    var children = [];

    function addPath(id, cmds, attrs) {
      paths.push({ id: id, commands: cmds });
      var node = { type: 'path', pathId: id };
      if (attrs) {
        for (var k in attrs) { node[k] = attrs[k]; }
      }
      children.push(node);
    }

    var us = [0, 0.5, 1];
    var titles = ['u = 0', 'u = 1/2', 'u = 1'];

    for (var i = 0; i < 3; i++) {
      var u = us[i];
      var cx = pw * (i + 0.5);
      var left = cx - neckHalf;
      var right = cx + neckHalf;
      var topY = Ym - u * h;
      var botY = topY + h;

      addPath('neckL' + i, visualSdk.polyline([[left, Ym], [left, neckBottom]]),
        { stroke: '#26354a', strokeWidth: 2, fill: 'none' });
      addPath('neckR' + i, visualSdk.polyline([[right, Ym], [right, neckBottom]]),
        { stroke: '#26354a', strokeWidth: 2, fill: 'none' });

      addPath('cork' + i, visualSdk.polyline([
        [cx - corkHalf, topY],
        [cx + corkHalf, topY],
        [cx + corkHalf, botY],
        [cx - corkHalf, botY],
        [cx - corkHalf, topY]
      ]), { fill: '#dcb98c', stroke: '#8a6335', strokeWidth: 2 });

      addPath('mouth' + i, visualSdk.polyline([[left - 20, Ym], [right + 20, Ym]]),
        { stroke: '#b3402f', strokeWidth: 2, fill: 'none' });

      if (u > 0) {
        var ax = left - 12;
        addPath('dx' + i, visualSdk.arrow(ax, Ym, ax, topY),
          { stroke: '#1f6f4a', strokeWidth: 2, fill: 'none' });
        children.push({
          type: 'label', text: 'x', x: ax - 10, y: (Ym + topY) / 2 + 4,
          fontSize: 12, fill: '#1f6f4a', textAnchor: 'middle'
        });
      }

      children.push({
        type: 'label', text: titles[i], x: cx, y: labelY,
        fontSize: 14, fill: '#26354a', textAnchor: 'middle'
      });
    }

    children.push({
      type: 'label', text: '拔塞过程：u = x / h', x: W / 2, y: H * 0.075,
      fontSize: 17, fill: '#1b2430', textAnchor: 'middle'
    });
    children.push({
      type: 'label', text: '木塞上移 x = u·h（三段位移按真实比例）', x: W / 2, y: H * 0.125,
      fontSize: 12, fill: '#4a5a70', textAnchor: 'middle'
    });

    children.push({
      type: 'label', text: '瓶口基准线', x: pw * 0.5 - neckHalf - 14, y: Ym - 8,
      fontSize: 11, fill: '#b3402f', textAnchor: 'middle'
    });

    children.push({
      type: 'label', text: '木塞底部到达瓶口', x: pw * 2.5, y: subY,
      fontSize: 11, fill: '#4a5a70', textAnchor: 'middle'
    });

    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
